 int fd=openat(dir,temporary,O_CREAT|O_EXCL|O_WRONLY|O_NOFOLLOW|O_CLOEXEC,0600);if(fd<0){close(dir);return -1;}
 const unsigned char *p=bytes;size_t left=length;int result=0;
 while(left){ssize_t n=write(fd,p,left);if(n<0&&errno==EINTR)continue;if(n<=0){result=-1;break;}p+=n;left-=(size_t)n;}
 if(!result&&(fchmod(fd,0600)||fsync(fd)))result=-1;
